    Label {
        Layout.fillWidth: true
        visible: root.mlBridge.statusText.length > 0
        color: Theme.fgDim
        font.pixelSize: Theme.caption
        wrapMode: Text.Wrap
        text: root.mlBridge.statusText
    }
}

