    RowLayout {
        anchors.fill: parent
        anchors.margins: Theme.spacingSm
        spacing: Theme.spacingSm

        // Plan 007 U4: Run is the app's primary action (CTA hierarchy) —
        // the accent highlight marks it; Stop stays secondary.
