        Label {
            text: root.optimizerBridge.stageText
            color: Theme.fg
            font.pixelSize: Theme.caption
        }
        Label {
            text: qsTr("calls %1").arg(root.optimizerBridge.costCalls)
            color: Theme.fgDim
            font.pixelSize: Theme.caption
        }
        Label {
            text: qsTr("min %1")
                      .arg(root.optimizerBridge.currentMinimum.toFixed(3))
            color: Theme.fgDim
            font.pixelSize: Theme.caption
        }
    }
}

