    cv::Mat inverse_edge = cv::Mat(height_, width_, CV_8UC1);
    inverse_edge = (255 - edge_image_);
    cv::distanceTransform(inverse_edge, distance_map_, cv::DIST_L1, 5, CV_8UC1);
}

