import QtQuick
import QtQuick.Window
import QtQml.Models
import jtml.exp 1.0

Window {
    id: root
    width: 660
    height: 460
    visible: true

    ListModel { id: model
        Component.onCompleted: {
            for (let i = 0; i < 500; ++i)
                model.append({ frameIndex: i, x: i, y: i*2, z: 0, xa: 0, ya: 0, za: 0 })
        }
    }
    QtObject {
        id: fakePose
        property var tableModel: model
        property int rowCount: model.count
        property bool dirty: false
        property string validationMessage: ""
        property var commitLog: []
        signal poseTableChanged()
        function setPoseValue(frame, modelIdx, axis, text) {
            const v = parseFloat(String(text).trim())
            if (isNaN(v)) { validationMessage = "bad"; return false }
            commitLog.push([frame, modelIdx, axis, v])
            return true
        }
    }
    QtObject {
        id: fakeStudy
        property int primaryModelIndex: 0
        property int currentFrame: 0
    }
    QtObject {
        id: fakeOpt
        property bool running: false
    }

    PosesTable {
        anchors.fill: parent
        poseBridge: fakePose
        studyBridge: fakeStudy
        optimizerBridge: fakeOpt
    }

    property string report: ""
    function log(s) { report += s + "\n"; print(s) }

    Component.onCompleted: {
        // Let the table build
        Qt.callLater(run1)
    }
    function run1() {
        const list = findChild(root, "poseTableList")
        const row3 = list.itemAtIndex(3)
        const cell = row3.children[1]
        cell.forceActiveFocus()
        // simulate typing: set edited via onTextEdited is impossible;
        // instead directly check capture + focus retention behavior
        log("captured tuple after focus: " + cell.commitFrame + "," + cell.commitModel + "," + cell.commitAxis)
        list.positionViewAtIndex(100, ListView.Center)
        Qt.callLater(run2)
    }
    function run2() {
        const list = findChild(root, "poseTableList")
        // The cell for row 3 is now pooled; find any pooled item with focus
        let focused = null
        const items = list.contentItem.children
        for (let i = 0; i < items.length; ++i) {
            if (items[i].activeFocus) focused = items[i]
        }
        log("after scroll-away: item with activeFocus found: " + (focused ? focused.index : "none"))
        list.positionViewAtIndex(0, ListView.Beginning)
        Qt.callLater(run3)
    }
    function run3() {
        const list = findChild(root, "poseTableList")
        const row3 = list.itemAtIndex(3)
        const cell = row3.children[1]
        log("after scroll-back, row3 cell activeFocus: " + cell.activeFocus)
        log("after scroll-back, row3 cell tuple: " + cell.commitFrame + "," + cell.commitModel + "," + cell.commitAxis)
        log("after scroll-back, row3 cell text: " + cell.text)
        Qt.quit()
    }
}
EOF
