import QtQuick
import QtQuick.Window
import QtQml.Models
import jtml.exp 1.0

Window {
    id: root
    width: 660
    height: 460
    visible: true

    Timer { interval: 25000; running: true; repeat: false
        onTriggered: { print("TIMEOUT REPORT:"); print(report); Qt.quit() }
    }

    ListModel { id: model
        Component.onCompleted: {
            for (let i = 0; i < 10; ++i)
                model.append({ frameIndex: i, x: i, y: i*2, z: 0, xa: 0, ya: 0, za: 0 })
        }
    }
    QtObject {
        id: fakePose
        property var tableModel: model
        property int rowCount: model.count
        property bool dirty: false
        property string validationMessage: ""
        property var commitLog: []
        signal poseTableChanged()
        function setPoseValue(frame, modelIdx, axis, text) {
            const v = parseFloat(String(text).trim())
            if (isNaN(v)) { validationMessage = "bad"; return false }
            commitLog.push([frame, modelIdx, axis, v])
            dirty = true
            return true
        }
    }
    QtObject {
        id: fakeStudy
        property int primaryModelIndex: 0
        property int currentFrame: 0
        property int rowCount: 10
    }
    QtObject {
        id: fakeOpt
        property bool running: false
    }

    PosesDialog {
        id: dialog
        poseBridge: fakePose
        studyBridge: fakeStudy
        optimizerBridge: fakeOpt
        onDiscardRequested: log("discardRequested FIRED (dirty-close guard)")
        onClosed: log("PosesDialog onClosed fired; dirty=" + fakePose.dirty + " commits=" + fakePose.commitLog.length)
    }

    property string report: ""
    function log(s) { report += s + "\n" }

    function findList() {
        function walk(o) {
            if (!o) return null
            if (o.objectName === "poseTableList") return o
            const kids = o.children ? o.children : (o.data ? o.data : [])
            for (let i = 0; i < kids.length; ++i) {
                const hit = walk(kids[i])
                if (hit) return hit
            }
            return null
        }
        return walk(root)
    }

    Component.onCompleted: { Qt.callLater(run1) }

    function run1() {
        dialog.open()
        Qt.callLater(run2)
    }
    function run2() {
        const list = findList()
        if (!list) { Qt.callLater(run2); return }
        const row0 = list.itemAtIndex(0)
        if (!row0) { Qt.callLater(run2); return }
        const cell = row0.children[1]
        if (!cell) { Qt.callLater(run2); return }
        cell.forceActiveFocus()
        // Simulate an in-flight edit: typed text + edited flag
        cell.text = "42.5"
        cell.edited = true
        log("mid-edit: cell focused=" + cell.activeFocus + " edited=" + cell.edited)
        // Close the dialog (Esc-equivalent) with the edit in flight
        dialog.close()
        Qt.callLater(run3)
    }
    function run3() {
        log("after close: commits=" + JSON.stringify(fakePose.commitLog) + " dirty=" + fakePose.dirty)
        log("after close: table exists=" + (findList() !== null))
        print("REPORT:")
        print(report)
        Qt.quit()
    }
}

